@startuml

class Kinepolis {}

class Cinema {
  + town : string
}

class Theatre {
  + name : string
}

class Movie {
  + title : string
}

class MovieCopy {
  + copyId : int
}

class Show {
  + startTime : datetime
  + isPublished : boolean
  + isCancelled : boolean
}

class Reservation {
  + reservationTime : datetime
  + isCancelled : boolean
}

class SeatReservation {
  + seatNumber : string
  + isCancelled : boolean
}

class Ticket {
  + seatNumber : string
  + isAnonymous : boolean
}

class CreditCard {
  + cardNumber : string
}

class Offer {
  + expiryDate : datetime
}

class FreeTicket {
  + sentDate : date
}

Kinepolis "1" *-- "*" Cinema
Cinema "1" *-- "*" Theatre
Cinema "1" *-- "*" MovieCopy
Theatre "1" *-- "*" Show
Movie "1" -- "*" MovieCopy
Show "1" *-- "*" SeatReservation
Show "1" -- "*" Ticket
Show "1" -- "0..1" Offer
Reservation "1" *-- "1" SeatReservation
Reservation "1" -- "1" CreditCard
Reservation "0..1" -- "0..1" Offer
Offer "0..1" -- "1" FreeTicket

@enduml

